"""Checks for the proofs in synthetic/linear-recurrence-*/PROOFS.md (generated by generators/linear_recurrence.py).

Every count is measured on the unchanged generated implementations: the naive recursion and the matrix power are
instrumented through their module globals (the recursion calls `solve`, and `solve` calls `_mul`, by global name),
and the DP is traced line by line with sys.settrace. The formulas are recomputed here independently of the
generator. Deterministic; no randomness.

Run:  python -m unittest tests.test_proofs_linrec
"""
import importlib.util
import json
import re
import sys
import unittest
from fractions import Fraction
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
ENTRIES = ([1, 0, 1], [1, 1, 1], [1, 1, 1, 1], [2, 3])
MATRIX_NS = [2 ** 8, 2 ** 16, 2 ** 32, 2 ** 64, 2 ** 128]


def load(path, name):
    spec = importlib.util.spec_from_file_location(name, path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


GEN = load(ROOT / "generators" / "linear_recurrence.py", "linear_recurrence_for_proof_tests")


def entry_dir(coeffs):
    return ROOT / "synthetic" / ("linear-recurrence-c" + "-".join(str(c) for c in coeffs))


def entry_json(coeffs):
    return json.loads((entry_dir(coeffs) / "entry.json").read_text(encoding="utf-8"))


def impl(coeffs, name):
    return load(entry_dir(coeffs) / "implementations" / f"{name}.py", f"proof_{name}_{'_'.join(map(str, coeffs))}")


def support(coeffs):
    return [i for i, c in enumerate(coeffs, 1) if c]


def reference(coeffs, n_max):
    """a(0..n_max) mod 2^64, computed directly from the recurrence."""
    k = len(coeffs)
    a = [0] * (k - 1) + [1]
    while len(a) <= n_max:
        n = len(a)
        a.append(sum(c * a[n - i] for i, c in enumerate(coeffs, 1)) % 2 ** 64)
    return a[:n_max + 1]


def calls_recurrence(coeffs, n_max):
    """(b): C(n) = 1 for n < k, 1 + sum_{i in S} C(n - i) otherwise."""
    k, S = len(coeffs), support(coeffs)
    C = []
    for n in range(n_max + 1):
        C.append(1 if n < k else 1 + sum(C[n - i] for i in S))
    return C


def g_recurrence(coeffs, n_max):
    k, S = len(coeffs), support(coeffs)
    G = []
    for n in range(n_max + 1):
        G.append(1 if n < k else sum(G[n - i] for i in S))
    return G


def char_poly(coeffs, x):
    k = len(coeffs)
    return x ** k - sum(x ** (k - i) for i in support(coeffs))


def lambda_bracket(coeffs, width=Fraction(1, 10 ** 30)):
    lo, hi = Fraction(1), Fraction(2)
    while hi - lo >= width:
        mid = (lo + hi) / 2
        if char_poly(coeffs, mid) < 0:
            lo = mid
        else:
            hi = mid
    return lo, hi


def table(proofs_text, header):
    """Rows (int, int) of the Markdown table whose header line starts with `header`."""
    lines = proofs_text.splitlines()
    i = next(j for j, line in enumerate(lines) if line.startswith(header))
    rows = []
    for line in lines[i + 2:]:
        if not line.startswith("|"):
            break
        a, b = [x.strip().strip("`") for x in line.strip("|").split("|")]
        rows.append((a, int(b)))
    return rows


class GeneratorReproducesEntries(unittest.TestCase):
    def test_proof_mark_only_for_the_checked_entries(self):
        self.assertEqual(set(GEN.PROOF_AUDITS), {tuple(c) for c in ENTRIES})

    def test_build_reproduces_every_file_byte_for_byte(self):
        for coeffs in ENTRIES:
            with self.subTest(coeffs=coeffs):
                files = GEN.build(coeffs)
                d = entry_dir(coeffs)
                on_disk = sorted(p.relative_to(d).as_posix() for p in d.rglob("*")
                                 if p.is_file() and "__pycache__" not in p.parts)
                self.assertEqual(on_disk, sorted(files))
                for rel, text in files.items():
                    self.assertEqual((d / rel).read_bytes(), text.encode("utf-8"), rel)


class Lambda(unittest.TestCase):
    def test_lambda(self):
        """Section 1: unique root in (1, 2), and the printed value is lambda rounded to 10 decimals."""
        for coeffs in ENTRIES:
            with self.subTest(coeffs=coeffs):
                cost = entry_json(coeffs)["algorithms"][0]["harness"]["scaling"]["cost"]
                lam_r = Fraction(cost.split("**")[0])
                self.assertLess(char_poly(coeffs, Fraction(1)), 0)
                self.assertGreater(char_poly(coeffs, Fraction(2)), 0)
                eps = Fraction(5, 10 ** 11)
                self.assertLess(char_poly(coeffs, lam_r - eps), 0)
                self.assertGreater(char_poly(coeffs, lam_r + eps), 0)
                self.assertEqual(cost.split("**")[0], f"{GEN.growth_rate(coeffs):.10f}")
                lo, hi = lambda_bracket(coeffs)
                self.assertTrue(lam_r - eps < lo < hi < lam_r + eps)


class Naive(unittest.TestCase):
    def test_naive(self):
        """Section 2: instrumented call counts and depth, (b) = (c), the bounds (d), and the PROOFS.md table."""
        for coeffs in ENTRIES:
            with self.subTest(coeffs=coeffs):
                e = entry_json(coeffs)
                k, S = len(coeffs), support(coeffs)
                s, i_min = len(S), min(S)
                v1_max = e["algorithms"][0]["harness"]["v1_max_n"]
                naive, dp = impl(coeffs, "naive"), impl(coeffs, "dp")
                original = naive.solve
                state = {"calls": 0, "internal": 0, "cur": 0, "max": 0}

                def counting(n, original=original, state=state, k=k):
                    state["calls"] += 1
                    state["internal"] += n >= k
                    state["cur"] += 1
                    state["max"] = max(state["max"], state["cur"])
                    try:
                        return original(n)
                    finally:
                        state["cur"] -= 1

                naive.solve = counting
                C = calls_recurrence(coeffs, 200)
                G = g_recurrence(coeffs, 200)
                ref = reference(coeffs, v1_max)
                for n in range(v1_max + 1):
                    state.update(calls=0, internal=0, cur=0, max=0)
                    value = naive.solve(n)
                    self.assertEqual(value, ref[n])
                    self.assertEqual(value, dp.solve(n))
                    self.assertEqual(state["calls"], C[n], n)
                    self.assertEqual(s * state["internal"], C[n] - 1, n)  # (e): (C(n) - 1)/s calls with n >= k
                    depth = 1 if n < k else 1 + -(-(n - k + 1) // i_min)
                    self.assertEqual(state["max"], depth, n)
                lo, hi = lambda_bracket(coeffs)
                ratio = Fraction(s, s - 1)
                for n in range(201):
                    self.assertEqual(s * G[n] - 1, (s - 1) * C[n])  # (c)
                    self.assertLessEqual(C[n], ratio * hi ** n)  # (d), upper bound (lambda < hi)
                    self.assertGreaterEqual(C[n], max(Fraction(1), lo ** (n - k + 1)))  # (d), lower (lo < lambda)
                rows = table((entry_dir(coeffs) / "PROOFS.md").read_text(encoding="utf-8"), "| n | C(n) calls |")
                expected = sorted(set([v1_max] + e["algorithms"][0]["harness"]["scaling"]["n_values"]))
                self.assertEqual([int(a) for a, _ in rows], expected)
                C_big = calls_recurrence(coeffs, max(expected))
                for a, b in rows:
                    self.assertEqual(b, C_big[int(a)])


class DP(unittest.TestCase):
    def test_dp(self):
        """Section 3: line counts and the largest window length of the unchanged dp.solve; agreement for n <= 2000."""
        for coeffs in ENTRIES:
            with self.subTest(coeffs=coeffs):
                k, s = len(coeffs), len(support(coeffs))
                dp, mp = impl(coeffs, "dp"), impl(coeffs, "matrix_power")
                src = (entry_dir(coeffs) / "implementations" / "dp.py").read_text(encoding="utf-8").splitlines()
                line_of = {key: next(i + 1 for i, line in enumerate(src) if line.strip() == text)
                           for key, text in (("append", "window.append(nxt & MASK)"), ("test", "if c:"),
                                             ("madd", "nxt += c * window[-i]"))}
                code = dp.solve.__code__
                for n in range(0, 301):
                    counts = {"append": 0, "test": 0, "madd": 0}
                    longest = [0]

                    def local(frame, event, arg, counts=counts, longest=longest):
                        if event == "line":
                            for key, ln in line_of.items():
                                if frame.f_lineno == ln:
                                    counts[key] += 1
                            w = frame.f_locals.get("window")
                            if w is not None:
                                longest[0] = max(longest[0], len(w))
                        return local

                    def tracer(frame, event, arg, code=code, local=local):
                        return local if frame.f_code is code else None

                    sys.settrace(tracer)
                    try:
                        dp.solve(n)
                    finally:
                        sys.settrace(None)
                    runs = max(0, n - k + 1)
                    self.assertEqual(counts, {"append": runs, "test": k * runs, "madd": s * runs}, n)
                    self.assertEqual(longest[0], k + 1 if n >= k else 0, n)
                ref = reference(coeffs, 2000)
                for n in range(0, 2001):
                    self.assertEqual(dp.solve(n), ref[n])
                    self.assertEqual(mp.solve(n), ref[n])


class MatrixPower(unittest.TestCase):
    def test_matrix_power(self):
        """Section 4: _mul calls = bit length + number of 1 bits of n - k + 1, all operands k x k; PROOFS.md table."""
        for coeffs in ENTRIES:
            with self.subTest(coeffs=coeffs):
                k = len(coeffs)
                mp, dp = impl(coeffs, "matrix_power"), impl(coeffs, "dp")
                original = mp._mul
                state = {"calls": 0, "bad_shape": 0}

                def counting(A, B, original=original, state=state, k=k):
                    state["calls"] += 1
                    for M in (A, B):
                        if len(M) != k or any(len(row) != k for row in M):
                            state["bad_shape"] += 1
                    return original(A, B)

                mp._mul = counting
                for n in list(range(0, 301)) + MATRIX_NS:
                    state.update(calls=0, bad_shape=0)
                    value = mp.solve(n)
                    if n <= 300:
                        self.assertEqual(value, dp.solve(n))
                    e = n - k + 1
                    expected = 0 if n < k else e.bit_length() + bin(e).count("1")
                    self.assertEqual(state["calls"], expected, n)
                    self.assertEqual(state["bad_shape"], 0, n)
                rows = table((entry_dir(coeffs) / "PROOFS.md").read_text(encoding="utf-8"), "| n | `_mul` calls |")
                self.assertEqual([a for a, _ in rows], [f"2^{n.bit_length() - 1}" for n in MATRIX_NS])
                for (a, b), n in zip(rows, MATRIX_NS):
                    e = n - k + 1
                    self.assertEqual(b, e.bit_length() + bin(e).count("1"))


class Caveats(unittest.TestCase):
    def test_harness_checks_only_the_initial_values(self):
        """Section 5: harness.check gives a verdict only for n < k."""
        for coeffs in ENTRIES:
            with self.subTest(coeffs=coeffs):
                k = len(coeffs)
                h = load(entry_dir(coeffs) / "harness.py", f"proof_harness_{'_'.join(map(str, coeffs))}")
                ref = reference(coeffs, 50)
                for n in range(51):
                    verdict = h.check(n, ref[n])
                    self.assertEqual(verdict, True if n < k else None, n)


if __name__ == "__main__":
    unittest.main()
